import time
def trial(n):
    primes = []
    for x in range(2, n):
        if all(x%d != 0 for d in range(2, int(x**0.5)+1)):
            primes.append(x)
    return len(primes)
t0 = time.time(); c = trial(100000); dt = time.time() - t0
print(f'{c} primes in {dt:.3f}s')

import time
def sieve(n):
    b = bytearray([1]) * n; b[0] = b[1] = 0
    for i in range(2, int(n**0.5)+1):
        if b[i]: b[i*i:n:i] = bytearray([0]) * len(b[i*i:n:i])
    return sum(b)
t0 = time.time(); c = sieve(100000); dt = time.time() - t0
print(f'{c} primes in {dt:.4f}s')

