import json
import math

# 1. Define JSON Schema for Tool
TOOLS_SCHEMA = [
    {
        "type": "function",
        "function": {
            "name": "calculator",
            "description": "Safely evaluates mathematical expressions",
            "parameters": {
                "type": "object",
                "properties": {
                    "expr": {"type": "string", "description": "Math expression, e.g. '(28.7/12.4)**0.2 - 1'"}
                },
                "required": ["expr"]
            }
        }
    }
]

# 2. Tool Execution Dispatcher
def execute_tool(name, args):
    if name == "calculator":
        allowed_names = {"math": math, "pow": pow, "abs": abs}
        return str(eval(args["expr"], {"__builtins__": {}}, allowed_names))
    return f"Error: Tool '{name}' not found"

# 3. Simulate ReAct Agent Thought-Action Loop
user_goal = "Calculate 5-year CAGR: $12.4M (2019) to $28.7M (2024)"
